// src/types/database.ts
// Database types — will be auto-generated by `npx supabase gen types typescript`
// These are placeholder types matching our schema for development

export type OrderStatus = 'pending' | 'confirmed' | 'preparing' | 'ready' | 'delivered' | 'cancelled'
// Per-line-item lifecycle. Enables Select Item(s)/Select All + partial ready/served.
// orders.status is the rolled-up aggregate of its items' statuses.
export type OrderItemStatus = 'pending' | 'preparing' | 'ready' | 'served' | 'cancelled'
export type SessionStatus = 'active' | 'closed' | 'expired'
export type PaymentStatus = 'unpaid' | 'pending' | 'paid' | 'refunded' | 'failed'
// 'owner' has no corresponding row in the `roles` table (custom_access_token_hook
// derives app_role from roles.name) — it's kept here because auth.ts and the
// billing actions already branch on it defensively for legacy/edge-case JWTs.
export type RoleName = 'super_admin' | 'manager' | 'kitchen' | 'waiter' | 'cashier' | 'customer' | 'owner'
export type PricingRuleType = 'percentage_off' | 'fixed_price' | 'amount_off'
export type PromoType = 'percentage_off' | 'amount_off' | 'free_item' | 'bogo'
export type LoyaltyTier = 'bronze' | 'silver' | 'gold' | 'platinum'
export type ServiceRequestType = 'call_waiter' | 'request_bill' | 'need_water' | 'clean_table' | 'other' | 'open_session'
export type ServiceRequestStatus = 'pending' | 'acknowledged' | 'completed' | 'cancelled'
export type SplitType = 'by_seat' | 'even' | 'custom' | 'full'
export type TakeoutStatus = 'placed' | 'confirmed' | 'preparing' | 'ready_for_pickup' | 'picked_up' | 'cancelled'
export type IngredientMovementType = 'purchase' | 'usage' | 'waste' | 'adjustment' | 'transfer'

export interface Role {
    id: number
    name: RoleName
    description: string | null
}

export type SubscriptionTier = 'free' | 'basic' | 'pro' | 'enterprise'
export type SubscriptionStatus = 'active' | 'past_due' | 'suspended' | 'cancelled'
export type PaymentMethod = 'qr_scan' | 'esewa' | 'khalti' | 'fonepay' | 'cash' | 'card'

